SELECT
    apd.ASSET_TYPE assetType,
    api.VDATE vdate,
    api.EDATE edate,
    apd.PLAN_INIT_AMT/10000    planInitAmt,
    apd.PLAN_CHANGE_AMT/10000  planChangeAmt,
    apd.PLAN_TARGET_AMT/10000  planTargetAmt,
    api.REMARK remark,
    api.ASSET_PLAN_CODE assetPlanCode
FROM
    ASSET_PLAN_INFO api
INNER JOIN ASSET_PLAN_DETAIL apd
    ON api.ASSET_PLAN_CODE = apd.ASSET_PLAN_CODE


        AND apd.ASSET_TYPE = #{assetType}





            AND DATE_FORMAT(api.VDATE,'%Y-%m-%d') >= #{vdate,jdbcType=VARCHAR}
            AND DATE_FORMAT(api.EDATE,'%Y-%m-%d') <= #{edate,jdbcType=VARCHAR}


            AND DATE_FORMAT(api.VDATE,'%Y-%m-%d') = #{vdate,jdbcType=VARCHAR}


            AND DATE_FORMAT(api.EDATE,'%Y-%m-%d') = #{edate,jdbcType=VARCHAR}








        AND DATE_FORMAT(api.BENCH_DATE,'%Y-%m-%d') = #{benchDate,jdbcType=VARCHAR}

select count(1)
from ASSET_PLAN_INFO

    DATE_FORMAT(vdate,'%Y-%m-%d') = #{vdate} AND DATE_FORMAT(edate,'%Y-%m-%d') = #{edate}

        AND ASSET_PLAN_CODE <> #{assetPlanCode}

select count(1) from ASSET_PLAN_INFO
( (DATE_FORMAT(vdate,'%Y-%m-%d') > #{vdate} AND DATE_FORMAT(vdate,'%Y-%m-%d') < #{edate}) or (DATE_FORMAT(edate,'%Y-%m-%d') > #{vdate} AND DATE_FORMAT(edate,'%Y-%m-%d') < #{edate}) or (DATE_FORMAT(vdate,'%Y-%m-%d') < #{vdate} AND DATE_FORMAT(edate, '%Y-%m-%d') > #{edate}) )
AND ASSET_PLAN_CODE <> #{assetPlanCode}
